DB=np.maximum(lo[:,None]-T[None],0); DA=np.maximum(T[None]-hi[:,None],0)
def pred3(th, kind):
    lam,lap,gy,k,lt=expit(th[0]),expit(th[1]),expit(th[2]),th[3],th[4]
    lp=-k*rel; lp=lp-logsumexp(lp)
    lr=np.log(lam)-np.log(R)+LL[:,:R]; li=np.log(1-lam)+lp[None]+LL[:,R:]
    allp=np.concatenate([lr,li],1); Z=logsumexp(allp,1,keepdims=True); P=np.exp(allp-Z)
    tau=np.exp(lt)
