    q=np.clip((P[:,:R]@MEM[:R]+P[:,R:]@IM)[si,ti],0,1)
    return np.clip((1-lap)*q+lap*gy,1e-6,1-1e-6)
def nll3(th,kd): p=pred3(th,kd); return -(y*np.log(p)+(1-y)*np.log(1-p)).sum()
